    out=head('contact')+f'''<main id="main" class="proposal-main"><section class="technical-intro"><span class="overline">ANDEAN SOFTWARE LAB</span>{t('Hablemos de<br><em>tu proyecto.</em>','Let’s talk about<br><em>your project.</em>','h1')}<p>{t('Cuéntanos qué estás comercializando y qué necesitan ver tus compradores. Podemos empezar con un piloto para un desarrollo y ampliar la experiencia después.','Tell us what you are selling and what your buyers need to see. We can start with a pilot for one development and expand the experience later.')}</p><div class="contact-options">{a('Escribir a Alvaro Paz ↗','Email Alvaro Paz ↗','mailto:alvaroipazr@gmail.com?subject=Demo%20inmobiliaria%20-%20mi%20proyecto','button')}<span>alvaroipazr@gmail.com</span>{a('Escribir a Martín Vélez Falconí','Email Martín Vélez Falconí','mailto:martinvelezf@hotmail.com?subject=Demo%20inmobiliaria%20-%20mi%20proyecto','text-link')}{a('Conocer al equipo','Meet the team','/nosotros/','text-link')}</div><p class="demo-disclosure">{t('Los enlaces abren tu aplicación de correo. Tú decides cuándo enviar el mensaje.','Links open your email application. You choose when to send the message.')}</p></section><section class="demo-journey contact-scope">{t('Para preparar una propuesta útil.','To prepare a useful proposal.','h2')}<ul><li>{t('El nombre del proyecto, ciudad y etapa de comercialización.','Project name, city and sales stage.')}</li><li>{t('Tu sitio actual y los planos, renders o tours disponibles.','Your current website and available plans, renders or tours.')}</li><li>{t('Qué quieres facilitar: presentación, selección de unidades o consultas comerciales.','What you want to improve: presentation, unit selection or sales enquiries.')}</li><li>{t('Las herramientas que usa tu equipo: WhatsApp, CRM o inventario.','Your team’s tools: WhatsApp, CRM or inventory.')}</li></ul><p>{t('El alcance y la inversión se definen para cada proyecto. Integramos activos existentes; la creación de nuevos modelos 3D, fotografía 360 o renders se evalúa por separado.','Scope and investment are defined for each project. We integrate existing assets; new 3D models, 360 photography or renders are assessed separately.')}</p></section></main>'''+footer(True)+'</body></html>'
